import {analyzeMultiSource} from '../src/checker/index.ts';
import {prepareWholeIrProgram} from '../src/ir/program-preparation.ts';
import {acceptPreparedIrProgram} from '../src/ir/program-consumer.ts';
import {forEachInstrDeep} from '../src/ir/core/nodes.ts';
for(const[name,source]of Object.entries({
 discard:'export function run(input:{n:number}):number{input.n;return 42;}',
 strict:'export function run(input:{n:number},value:number):number{input.n=value;return value;}',
 sloppy:'function run(input:{n:number},value:number):number{input.n=value;return value;}',
 nested:'type Child={n:number};type Outer={child:Child};export function echo(input:Outer):Outer{return input;}'
})){
 const graph=analyzeMultiSource({'./entry.ts':source},'./entry.ts');
 const prepared=prepareWholeIrProgram({sourceFiles:graph.sourceFiles,entrySource:graph.entryFile,checker:graph.checker,deferTopLevelInit:false,policy:{backend:'wasmgc',target:'standalone'},objectReferenceProjection:'live'} as any);
 if(prepared.kind!=='prepared')throw Error(JSON.stringify(prepared));
 const program=prepared.program,rows:any[]=[];
 for(const fn of program.ir.functions)for(const block of fn.blocks)for(const root of block.instrs)forEachInstrDeep(root,row=>rows.push(row));
 const providers=program.abi.entries.filter(e=>e.contract.kind==='callable'&&e.contract.ref.binding.kind==='support');
 const accepted=acceptPreparedIrProgram(program,{backend:'wasmgc',target:'standalone'});
 console.log(JSON.stringify({name,sourceSha256:createHash('sha256').update(source).digest('hex'),prepared:prepared.kind,functions:program.ir.functions.length,logicalPlanShapes:(program as any).objectReferences?.shapes.length??0,providerDeclarations:providers.map(e=>({id:e.plan.id,contract:e.contract})),rawProperties:rows.filter(r=>r.kind==='object.get'||r.kind==='object.set').map(r=>({kind:r.kind,failureMode:r.failureMode})),propertyCalls:rows.filter(r=>r.kind==='call'&&r.target.binding.kind==='support').map(r=>({binding:r.target.binding,resultType:r.resultType,args:r.args})),acceptance:accepted.kind,...(accepted.kind==='unsupported'?{detail:accepted.detail}:{})}));
}

